package org.example;

import java.util.List;
import java.util.Scanner;

public class App {

    public static void main(String[] args) {
        printGrammar();

        Scanner scanner = new Scanner(System.in);

        while (true) {
            System.out.println("\nВведите арифметическое выражение (или exit для выхода):");

            if (!scanner.hasNextLine()) {
                System.out.println("Ввод завершён.");
                break;
            }

            String expression = scanner.nextLine().trim();

            if (expression.equalsIgnoreCase("exit")) {
                System.out.println("Завершение программы.");
                break;
            }

            if (expression.isEmpty()) {
                System.out.println("Выражение не введено.");
                continue;
            }

            try {
                Lexer lexer = new Lexer(expression);
                List<Token> tokens = lexer.tokenize();

                Parser parser = new Parser(tokens);
                Node tree = parser.parseS();

                System.out.println("\n=== Дерево разбора ===");
                tree.printTree();

                if (parser.hasError()) {
                    System.out.println("\nВыражение некорректно.");
                    System.out.println(parser.getErrorMessage());
                } else {
                    System.out.println("\nВыражение корректно.");
                }

            } catch (RuntimeException e) {
                System.out.println("\nВыражение некорректно.");
                System.out.println(e.getMessage());
            }
        }

        scanner.close();
    }

    private static void printGrammar() {
        System.out.println("========================================");
        System.out.println("     СИНТАКСИЧЕСКИЙ АНАЛИЗАТОР");
        System.out.println("========================================");

        System.out.println("\nОписание:");
        System.out.println(
                "Программа выполняет лексический и синтаксический анализ "
                        + "арифметических выражений."
        );
        System.out.println(
                "Лексер выделяет числа, идентификаторы и знаки операций, "
                        + "а парсер проверяет соответствие выражения грамматике "
                        + "и строит дерево разбора."
        );

        System.out.println("\nГрамматика:");

        System.out.println("S  -> E");
        System.out.println("E  -> T E'");
        System.out.println("E' -> + T E' | - T E' | ε");
        System.out.println("T  -> F T'");
        System.out.println("T' -> * F T' | / F T' | ε");
        System.out.println("F  -> ( E ) | number | id");

        System.out.println("\nОбозначения:");
        System.out.println("S      — начальный символ грамматики");
        System.out.println("E      — выражение");
        System.out.println("E'     — продолжение выражения (+ или -)");
        System.out.println("T      — терм");
        System.out.println("T'     — продолжение терма (* или /)");
        System.out.println("F      — множитель: число, идентификатор или выражение в скобках");
        System.out.println("number — целое число");
        System.out.println("id     — идентификатор, например x или value_1");
        System.out.println("ε      — пустая последовательность");

        System.out.println("\n========================================");
    }
}